# Load libraries
library(shiny)
library(dplyr)
library(readr)
library(sf)
library(spData)
library(leaflet)
library(DT)

# Load world map data
data(world)

# Load your dataset (TSV format)
full_data <- read_tsv("data/Data_massaged.tsv", show_col_types = FALSE)

# Define filterable columns
filter_columns <- c("Pathogen", "Disease", "Host", "Country", "Year")

# Define broad non-country locations to exclude from z-score map
excluded_locations <- c("#noLOC","Africa","American Samoa","Amsterdam Island","Asia","Barbados","Canary Islands",
                        "Cape Verde","Corsica","East Africa","Europe","French West Indies","Gambia",
                        "Grande Comore and Anjouan","Grande Comoros Island","Guadeloupe","Guadeloupe, French West Indies","Guam",
                        "Hong Kong","Island of Reunion","Mauritius","Mauritius island","Mayotte","Nevis Island","Reunion",
                        "Reunion Island","Seychelles","Singapore","South America","South Asia","Tuvalu","Yugoslavia",
                        "Grand Bahama Island","French Guiana","French Guyana","Belgium and Germany","Belgium and the Netherlands","Benin and Nigeria",
                        "Benin, Ghana, and Nigeria","Benin, Nigeria, and Togo","Ivory Coast and Cameroon","Canada and USA","Costa Rica and Nicaragua","France and Italy",
                        "France, Italy, and China","Germany and The Netherlands","Germany, Switzerland, and Italy","Ghana, Togo, and Republic of Benin",
                        "India and Indonesia","Jordan, Lebanon, Syria, and Tunisia","Kenya and Uganda","Malawi and Mozambique","Martinique",
                        "Martinique and Guadeloupe","Martinique island","Mexico and Guatemala","Mexico, El Salvador, and Panama",
                        "Pakistan and Lebanon","Portugal and in Spain","Spain and Egypt","Turkey and Germany","Turkey and Greece",
                        "Turkey and Tunisia","USA and Canada","USA and Malaysia","USA and Netherlands","USA and New Zealand",
                        "USA, Japan, Italy, Spain, and New Zealand","Vietnam and Lao PDR","Serbia and Montenegro",
                        "Africa", "Asia", "Europe", "North America", "South America",
                        "Middle East", "Central America", "Southeast Asia", "World", "Global",
                        "Oceania", "Caribbean", "Sub-Saharan Africa", "Northern Africa",
                        "Southern Africa", "Eastern Europe", "Western Europe", "East Asia",
                        "South Asia", "Central Asia", "Pacific Islands")

